import shlex

def handle(query, state):
    """Simulate an archive extraction service.
    Users submit an archive name and an optional member path to extract.
    Internally the service builds a shell command like:
        tar xf <archive> --to-stdout <member>
    and evaluates it against an in-memory filesystem.
    The 'archive' parameter is interpolated unsafely, allowing command injection.
    """
    archive = (query.get("archive") or ["backup.tar"])[0]
    member  = (query.get("member")  or [""])[0]

    files     = state.get("files", {})
    archives  = state.get("archives", {})

    def _run_cmd(cmd_str):
        cmd_str = cmd_str.strip()
        if not cmd_str:
            return ""
        try:
            parts = shlex.split(cmd_str)
        except ValueError:
            return "[parse error]"
        if not parts:
            return ""
        prog = parts[0]
        args = parts[1:]

        if prog == "tar":
            # Supported: tar xf <archive> [--to-stdout <member>]
            # Drop flags we don't care about
            positional = [a for a in args if not a.startswith("-")]
            # positional[0] = archive name, positional[1] = member (after --to-stdout)
            arc_name = positional[0] if positional else ""
            to_stdout_idx = None
            for i, a in enumerate(args):
                if a == "--to-stdout" and i + 1 < len(args):
                    to_stdout_idx = i + 1
            mbr = args[to_stdout_idx] if to_stdout_idx is not None else ""

            arc = archives.get(arc_name)
            if arc is None:
                return f"tar: {arc_name}: Cannot open: No such file or directory"
            if mbr:
                content = arc.get(mbr)
                if content is None:
                    return f"tar: {mbr}: Not found in archive"
                return content
            else:
                # List archive contents
                return "\n".join(arc.keys())

        elif prog == "cat":
            path = args[0] if args else ""
            content = files.get(path)
            if content is None:
                return f"cat: {path}: No such file or directory"
            return content

        elif prog == "ls":
            path = args[0] if args else "/"
            entries = set()
            for fp in files:
                if fp.startswith(path.rstrip("/") + "/"):
                    remainder = fp[len(path.rstrip("/")) + 1:]
                    top = remainder.split("/")[0]
                    entries.add(top)
            for arc_name in archives:
                entries.add(arc_name)
            return "\n".join(sorted(entries)) if entries else ""

        elif prog == "echo":
            return " ".join(args)

        elif prog == "id":
            return "uid=1000(extractor) gid=1000(extractor) groups=1000(extractor)"

        else:
            return f"{prog}: command not found"

    def _eval_chain(cmd_str):
        """Evaluate a semicolon-separated command chain.
        Intentionally does NOT filter the archive name before interpolation.
        """
        segments = []
        current  = []
        in_sq = False
        in_dq = False
        for ch in cmd_str:
            if ch == "'" and not in_dq:
                in_sq = not in_sq
                current.append(ch)
            elif ch == '"' and not in_sq:
                in_dq = not in_dq
                current.append(ch)
            elif ch == ";" and not in_sq and not in_dq:
                segments.append("".join(current))
                current = []
            else:
                current.append(ch)
        segments.append("".join(current))

        outputs = []
        for seg in segments:
            out = _run_cmd(seg)
            if out:
                outputs.append(out)
        return "\n".join(outputs)

    # The archive name is concatenated directly into the shell command — injection point.
    if member:
        cmd = f"tar xf {archive} --to-stdout {member}"
    else:
        cmd = f"tar xf {archive}"

    output = _eval_chain(cmd)

    body = (
        "<html><head><title>Archive Extractor</title></head><body>"
        "<h1>Archive Extractor Service</h1>"
        f"<h2>Archive: {archive}</h2>"
        "<pre>" + output + "</pre>"
        "</body></html>"
    )
    return 200, {"Content-Type": "text/html"}, body
